---
import { cn } from '@/utils/cn';
import type { HTMLAttributes } from 'astro/types';

export interface Props extends HTMLAttributes<'div'> {
  /** When true, selecting an item does not close the menu (e.g. color pickers). */
  keepOpen?: boolean;
}

const { class: className, keepOpen = false, ...props } = Astro.props;
---

<div
  class={cn('relative inline-block text-left', className)}
  data-dropdown
  data-dropdown-keep-open={keepOpen ? 'true' : undefined}
  {...props}
>
  <slot />
</div>

<script>
  import { registerUiInit } from "@/utils/runtime/loader";
  import { initDropdowns } from "@/utils/runtime/dropdown-menu";

  registerUiInit(initDropdowns);
</script>

---
import { cn } from '@/utils/cn';
import type { HTMLAttributes } from 'astro/types';

export interface Props extends HTMLAttributes<'div'> {
  align?: 'start' | 'center' | 'end';
  side?: 'bottom' | 'left' | 'right';
}

const {
  align = 'end',
  side = 'bottom',
  class: className,
  ...props
} = Astro.props;

const classes = cn(
  'z-50 min-w-[8rem] overflow-hidden rounded-lg border bg-popover p-1 text-popover-foreground shadow-md',
  className
);
---

<div
  class={classes}
  data-dropdown-content
  data-side={side}
  data-align={align}
  role="menu"
  hidden
  {...props}
>
  <slot />
</div>

---
import { cn } from '@/utils/cn';
import type { HTMLAttributes } from 'astro/types';

export interface Props extends Omit<HTMLAttributes<'a'>, 'type'> {
  href?: string;
  disabled?: boolean;
  destructive?: boolean;
}

const {
  href,
  disabled = false,
  destructive = false,
  class: className,
  ...props
} = Astro.props;

const classes = cn(
  'relative flex w-full cursor-pointer select-none items-center rounded-sm px-2 py-1.5 text-sm outline-none transition-colors',
  'focus:bg-accent focus:text-accent-foreground',
  'hover:bg-accent hover:text-accent-foreground',
  disabled && 'pointer-events-none opacity-50',
  destructive && 'text-destructive focus:text-destructive',
  className
);
---

{href ? (
  <a
    href={href}
    class={classes}
    role="menuitem"
    aria-disabled={disabled ? 'true' : undefined}
    tabindex="-1"
    data-dropdown-item
    {...props}
  >
    <slot />
  </a>
) : (
  <button
    type="button"
    class={classes}
    role="menuitem"
    disabled={disabled}
    tabindex="-1"
    data-dropdown-item
    {...props}
  >
    <slot />
  </button>
)}

